// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address payer, uint256 newTimestamp) public {
        vm.assume(payer != address(0));
        vm.assume(payer != address(this));

        uint256 cur = block.timestamp;
        uint256 ts = bound(newTimestamp, cur + 1, cur + 100000);

        uint256 b = block.number;
        uint256 targetBlock = b + 1;
        uint256 rem = targetBlock % 15;
        if (rem != 0) {
            targetBlock += (15 - rem);
        }
        vm.roll(targetBlock);
        vm.warp(ts);

        vm.deal(payer, 20 ether);
        vm.prank(payer);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        assertTrue(address(c).balance == 0);
    }
}
